  522: const inScope = (task: CrossReviewTask, file: string): boolean =>
  523:     task.writableScope.length === 0 ||
  524:     task.writableScope.some((scope) => file === scope || file.startsWith(scope.endsWith("/") ? scope : `${scope}/`));
  525: 
  526: const scopeViolations = (task: CrossReviewTask, files: readonly string[]): readonly string[] =>
  527:     files.filter((file) => !inScope(task, file));
