  529: // ---------------------------------------------------------------------------
  530: // Rules a person-driven exchange applies before a package or a review.
  531: 
  532: /** How many times a concluded exchange may be continued by a new task. */
  533: export const MAX_SUPERSESSIONS = 2;
  534: 
  535: const underPath = (file: string, path: string): boolean =>
  536:     path === "" || path === "." || file === path || file.startsWith(path.endsWith("/") ? path : `${path}/`);
  537: 
  538: /**
  539:  * One spelling for a repository path: forward slashes, no `./` prefix, no
  540:  * trailing slash. Every path that is compared, digested or handed to git
  541:  * goes through this once, so a Windows spelling and a POSIX spelling of the
  542:  * same file cannot pass one check and fail another.
  543:  */
  544: export const normalizeRepoPath = (path: string): string =>
  545:     path
  546:         .trim()
  547:         .replace(/\\/g, "/")
  548:         .replace(/^(\.\/)+/, "")
  549:         .replace(/\/+$/, "");
  550: 
  551: /**
  552:  * Why a set of `--diff-exclude` paths may not be applied to a package. A
  553:  * path is allowed only when it is exactly one of the task's generated paths,
  554:  * or the package's own output directory or something under it -- and never
  555:  * when it is, or contains, a path of the writable scope, whatever else it
  556:  * is: excluding a scoped source or a parent of one would leave the change
  557:  * unread and undigested. So `--out=. --diff-exclude=.` is refused, as is a
  558:  * parent of the package directory, as is a generated path that names a
  559:  * whole scope entry.
  560:  */
  561: export const packageExclusionProblems = (input: {
  562:     excluded: readonly string[];
  563:     generatedPaths: readonly string[];
  564:     outDir: string;
  565:     writableScope: readonly string[];
  566: }): readonly string[] => {
  567:     const out = normalizeRepoPath(input.outDir);
  568:     const generated = input.generatedPaths.map(normalizeRepoPath);
  569:     const scope = input.writableScope.map(normalizeRepoPath);
  570:     // A package directory that is, or contains, a scope entry (`--out=.`)
  571:     // would make every scoped file "under the package directory".
  572:     const outCoversScope = scope.filter((entry) => underPath(entry, out));
  573:     const problems: string[] = [];
  574:     for (const raw of input.excluded) {
  575:         const path = normalizeRepoPath(raw);
  576:         const covered = scope.filter((entry) => underPath(entry, path));
  577:         if (covered.length > 0) {
  578:             problems.push(`${raw} is, or contains, the writable scope entry ${covered.join(", ")}; a scoped source cannot be excluded from the reviewed diff`);
  579:             continue;
  580:         }
  581:         if (generated.includes(path)) continue;
  582:         if (underPath(path, out)) {
  583:             if (outCoversScope.length > 0) {
  584:                 problems.push(
  585:                     `${raw} is under the package directory ${input.outDir}, which is or contains the writable scope entry ${outCoversScope.join(", ")}; nothing under such a directory may be excluded`
  586:                 );
  587:             }
  588:             continue;
  589:         }
  590:         if (underPath(out, path)) {
  591:             problems.push(`${raw} contains the package directory ${input.outDir}; exclude the package directory itself, not a parent of it`);
  592:             continue;
  593:         }
  594:         problems.push(`${raw} is not one of the task's generatedPaths and is not the package directory`);
  595:     }
  596:     return problems;
  597: };
