  599: /** What a superseded exchange must look like for a task to continue it. */
  600: export type SupersededExchange = {
  601:     taskId: string;
  602:     status: string;
  603:     findings: readonly DisposedFinding[];
  604:     /** The exchanges that exchange itself continued, oldest first. */
  605:     lineage?: readonly string[];
  606: };
  607: 
  608: /**
  609:  * Why a task may not continue the exchange it names. A continuation is for a
  610:  * concluded exchange only -- on hold or failed, never passed or still open --
  611:  * and the chain of continuations is capped, so starting a new task is not a
  612:  * way to reset the revision cap.
  613:  */
  614: export const supersessionProblems = (task: CrossReviewTask, prior: SupersededExchange | null): readonly string[] => {
  615:     if (!task.supersedes) return [];
  616:     if (!prior) return [`${task.supersedes.exchange} could not be read`];
  617:     const problems: string[] = [];
  618:     if (prior.taskId !== task.supersedes.taskId) {
  619:         problems.push(`the exchange at ${task.supersedes.exchange} is ${prior.taskId}, not ${task.supersedes.taskId}`);
  620:     }
  621:     if (prior.status !== "on_hold" && prior.status !== "failed") {
  622:         problems.push(`the exchange ${prior.taskId} is ${prior.status}; only an exchange on hold or failed can be continued`);
  623:     }
  624:     const priorDepth = prior.lineage?.length ?? 0;
  625:     if (priorDepth + 1 > MAX_SUPERSESSIONS) {
  626:         problems.push(
  627:             `${prior.taskId} is already ${priorDepth} continuation(s) deep; the cap is ${MAX_SUPERSESSIONS}, and a person decides what happens to the change`
  628:         );
  629:     }
  630:     return problems;
  631: };
  632: 
  633: /** The findings a continuation inherits: those the prior exchange left open, as plain findings. */
  634: export const inheritedFindings = (prior: SupersededExchange): readonly Finding[] =>
  635:     prior.findings
  636:         .filter((finding) => finding.disposition === "unresolved_on_hold" || finding.disposition === "fix_requested")
  637:         .map((finding) => ({
  638:             location: finding.location,
  639:             severity: finding.severity,
  640:             basis: finding.basis,
  641:             claim: finding.claim,
  642:             ...(finding.reproduction !== undefined ? { reproduction: finding.reproduction } : {}),
  643:         }));
  644: 
  645: /** The lineage a continuation records: the prior's lineage, then the prior. */
  646: export const lineageOf = (prior: SupersededExchange): readonly string[] => [...(prior.lineage ?? []), prior.taskId];
