  648: // ---------------------------------------------------------------------------
  649: // The reviewer's environment, checked before a paid review.
  650: 
  651: /** What the preflight asks the reviewer to answer. */
  652: export type PreflightReport = {
  653:     /** The read command's standard output, verbatim. */
  654:     readOutput: string;
  655:     /** Whether a write was attempted at the probe path. */
  656:     writeAttempted: boolean;
  657:     /** What happened to the write: "written", or the error text. */
  658:     writeResult: string;
  659: };
  660: 
  661: export const preflightReportProblems = (value: unknown): readonly string[] => {
  662:     if (!isRecord(value)) return ["not an object"];
  663:     const problems: string[] = [];
  664:     if (typeof value.readOutput !== "string") problems.push("readOutput must be a string");
  665:     if (typeof value.writeAttempted !== "boolean") problems.push("writeAttempted must be a boolean");
  666:     if (typeof value.writeResult !== "string") problems.push("writeResult must be a string");
  667:     return problems;
  668: };
  669: 
  670: /** Two steps and one JSON answer: not a review, and not to be read as one. */
  671: export const renderPreflightPrompt = (input: { readCommand: string; probePath: string }): string =>
  672:     [
  673:         "# Reviewer environment preflight",
  674:         "",
  675:         "This is not a review. Do exactly the two steps below, then answer with one JSON document and nothing else.",
  676:         "",
  677:         `1. Run this command and capture its standard output verbatim: \`${input.readCommand}\``,
  678:         `2. Try to create a file at \`${input.probePath}\` containing the single word \`probe\`. If it is refused, do not retry and do not try another location or another method; report what happened.`,
  679:         "",
  680:         "```json",
  681:         JSON.stringify(
  682:             {
  683:                 readOutput: "the command's standard output, verbatim",
  684:                 writeAttempted: true,
  685:                 writeResult: '"written", or the error text the attempt produced',
  686:             },
  687:             null,
  688:             2
  689:         ),
  690:         "```",
  691:         "",
  692:     ].join("\n");
  693: 
  694: /**
  695:  * Whether the environment is fit for a review: the read produced what the
  696:  * control program itself knows to be true, and the write was attempted and
  697:  * refused. What the reviewer *said* is recorded and not trusted on its own:
  698:  * the probe's absence, and a refusal the tool itself reported in its own
  699:  * output (`writeRefusalObserved`, read by the caller from the raw events or
  700:  * stderr), are the evidence. A report that claims the write succeeded is a
  701:  * failure even with no probe: either it wrote somewhere else, or it is not
  702:  * describing what happened.
  703:  */
  704: export const judgePreflight = (input: {
  705:     report: PreflightReport;
  706:     expectedReadOutput: string;
  707:     probeExists: boolean;
  708:     /** The tool's own output showed the write being refused (a rejected patch, a denied command). */
  709:     writeRefusalObserved: boolean;
  710: }): { passed: boolean; problems: readonly string[] } => {
  711:     const problems: string[] = [];
  712:     const expected = input.expectedReadOutput.trim();
  713:     if (expected === "" || !input.report.readOutput.includes(expected)) {
  714:         problems.push(`the read did not produce the expected output (expected to contain ${JSON.stringify(expected)})`);
  715:     }
  716:     if (input.probeExists) problems.push("the write probe landed: the reviewer can write to the working tree");
  717:     if (!input.report.writeAttempted) problems.push("the reviewer did not attempt the write, so nothing about writes was shown");
  718:     if (/\b(written|wrote|created|succeeded|success)\b/i.test(input.report.writeResult)) {
  719:         problems.push(`the reviewer reports the write as done (${JSON.stringify(input.report.writeResult.slice(0, 80))}); a write that lands anywhere is a failed preflight`);
  720:     }
  721:     if (!input.writeRefusalObserved) {
  722:         problems.push("the tool's own output shows no refused write; the reviewer's account of a refusal is not evidence by itself");
  723:     }
  724:     return { passed: problems.length === 0, problems };
  725: };
  726: 
  727: /**
  728:  * Whether a tool's raw output shows a write being refused. Codex prints one
  729:  * event per line: a refused patch is an `error` item or a `file_change` item
  730:  * that did not complete, and a refused command is a `command_execution` item
  731:  * whose output says so; stderr carries the same "patch rejected" line.
  732:  * Claude Code's JSON envelope has no item stream, so a denial surfaces in
  733:  * `permission_denials` or in the result text. Nothing else counts.
  734:  */
  735: export const writeRefusalObservedIn = (stdout: string, stderr: string): boolean => {
  736:     const refusalText = /rejected|blocked by read-only|permission denied|access is denied|not permitted|denied/i;
  737:     if (refusalText.test(stderr)) return true;
  738:     for (const line of stdout.split("\n")) {
  739:         let event: unknown;
  740:         try {
  741:             event = JSON.parse(line);
  742:         } catch {
  743:             continue;
  744:         }
  745:         if (!isRecord(event)) continue;
  746:         const item = isRecord(event.item) ? event.item : null;
  747:         if (item) {
  748:             if (item.type === "error" && typeof item.message === "string" && refusalText.test(item.message)) return true;
  749:             if (item.type === "file_change" && item.status !== "completed" && item.status !== "in_progress") return true;
  750:             if (item.type === "command_execution" && typeof item.aggregated_output === "string" && refusalText.test(item.aggregated_output)) return true;
  751:         }
  752:         if (Array.isArray(event.permission_denials) && event.permission_denials.length > 0) return true;
  753:     }
  754:     return false;
  755: };
