  134:     /** Fixed arguments. Per-run configuration overrides, if any, come after them. */
  135:     args: readonly string[];
  136:     /**
  137:      * The flag that carries one `key=value` configuration override, for a
  138:      * tool that has one (`codex -c`). A tool without one refuses overrides.
  139:      */
  140:     configFlag?: string;
  141:     /** The final argument that makes the tool read its prompt from stdin, for a tool that needs one (`codex exec -`). */
  142:     promptArg?: string;
  143:     /** What the invocation is for and what was checked, so a reader can compare it with `--help`. */
  144:     note: string;
  145: };
