  215: export type CliCommandLine = { ok: true; args: readonly string[] } | { ok: false; detail: string };
  216: 
  217: /**
  218:  * The full argument list for one run: the fixed arguments, then one
  219:  * `configFlag key=value` per override, then the stdin marker. Overrides are
  220:  * refused for a tool without a config flag, when malformed, and -- when an
  221:  * allow list is given -- for any key outside it.
  222:  */
  223: export const cliCommandLine = (
  224:     invocation: CliInvocation,
  225:     configOverrides: readonly string[] = [],
  226:     allowedKeys: readonly string[] | null = null
  227: ): CliCommandLine => {
  228:     if (configOverrides.length > 0 && !invocation.configFlag) {
  229:         return { ok: false, detail: `${invocation.command} takes no configuration override; got ${configOverrides.join(", ")}` };
  230:     }
  231:     const overrideArgs: string[] = [];
  232:     for (const override of configOverrides) {
  233:         const separator = override.indexOf("=");
  234:         const key = separator === -1 ? "" : override.slice(0, separator).trim();
  235:         if (key === "") return { ok: false, detail: `a configuration override must be key=value; got \`${override}\`` };
  236:         if (allowedKeys && !allowedKeys.includes(key)) {
  237:             return {
  238:                 ok: false,
  239:                 detail: `configuration override \`${key}\` is not allowed for this role; allowed: ${allowedKeys.join(", ")}`,
  240:             };
  241:         }
  242:         overrideArgs.push(invocation.configFlag as string, override);
  243:     }
  244:     return { ok: true, args: [...invocation.args, ...overrideArgs, ...(invocation.promptArg ? [invocation.promptArg] : [])] };
  245: };
  246: 
  247: export type CliExecutorOptions = {
  248:     id: string;
  249:     invocation: CliInvocation;
  250:     mode: Exclude<ExecutorMode, "mock">;
  251:     cwd: string;
  252:     timeoutMs: number;
  253:     /** Required for `live`; ignored -- never called -- in `dry-run`. */
  254:     spawn?: Spawner;
  255:     env?: Record<string, string | undefined>;
  256:     /** `key=value` configuration overrides, each passed with the invocation's `configFlag`. */
  257:     configOverrides?: readonly string[];
  258: };
  259: 
  260: const notExecuted = <T>(mode: string, command: string, args: readonly string[]): ExecutorResult<T> => ({
  261:     ok: false,
  262:     failure: "not_executed",
  263:     detail: `${mode}: would run \`${[command, ...args].join(" ")}\` with the prompt on stdin`,
  264: });
  265: 
  266: const runCli = async <T>(
  267:     options: CliExecutorOptions,
  268:     role: CrossReviewRole,
  269:     prompt: string,
  270:     problemsOf: (value: unknown) => readonly string[]
  271: ): Promise<ExecutorResult<T>> => {
  272:     const line = cliCommandLine(
  273:         options.invocation,
  274:         options.configOverrides ?? [],
  275:         role === "reviewer" ? REVIEWER_CONFIG_OVERRIDE_KEYS : null
  276:     );
  277:     if (!line.ok) return { ok: false, failure: "execution_failed", detail: line.detail };
  278:     if (options.mode === "dry-run") return notExecuted<T>("dry-run", options.invocation.command, line.args);
  279:     if (!options.spawn) {
  280:         return { ok: false, failure: "execution_failed", detail: "live mode with no spawner; nothing was run" };
  281:     }
  282:     let result: SpawnResult;
  283:     try {
  284:         result = await options.spawn(options.invocation.command, line.args, {
  285:             input: prompt,
  286:             cwd: options.cwd,
  287:             timeoutMs: options.timeoutMs,
  288:             env: options.env,
  289:         });
  290:     } catch (error) {
  291:         return { ok: false, failure: "execution_failed", detail: error instanceof Error ? error.message : String(error) };
  292:     }
  293:     if (result.timedOut) return { ok: false, failure: "timeout", detail: `${options.invocation.command} exceeded ${options.timeoutMs}ms` };
  294:     if (result.error) return { ok: false, failure: "execution_failed", detail: result.error.message };
  295:     if (result.status !== 0) {
  296:         return {
  297:             ok: false,
  298:             failure: "execution_failed",
  299:             detail: `${options.invocation.command} exited ${result.status}: ${result.stderr.trim().slice(0, 400)}`,
  300:         };
  301:     }
  302:     return parseExecutorJson<T>(unwrapCodexJsonl(unwrapClaudeResult(result.stdout)), problemsOf);
  303: };
  304: 
  305: /**
  306:  * Codex's `exec --json` prints one event per line; the model's final message
  307:  * arrives as `{"type":"item.completed","item":{"id":…,"type":"agent_message",
  308:  * "text":…}}` (`codex-rs/exec/src/exec_events.rs` at tag `rust-v0.146.0`:
  309:  * `ThreadEvent` tagged by `type`, `ThreadItem` flattening `ThreadItemDetails`
  310:  * tagged by `type`, `AgentMessageItem { text }`). That text is the document
  311:  * asked for; the last such message wins. The older `{"msg":{"type":
  312:  * "agent_message","message":…}}` shape is read too. Output that is not JSONL
  313:  * is returned untouched for the parser to judge.
  314:  */
  315: export const unwrapCodexJsonl = (stdout: string): string => {
  316:     const lines = stdout.split("\n").map((line) => line.trim()).filter(Boolean);
  317:     if (lines.length === 0) return stdout;
  318:     let last: string | null = null;
  319:     for (const line of lines) {
  320:         let event: unknown;
  321:         try {
  322:             event = JSON.parse(line);
  323:         } catch {
  324:             return stdout;
  325:         }
  326:         if (typeof event !== "object" || event === null) continue;
  327:         const item = (event as { item?: { type?: unknown; text?: unknown } }).item;
  328:         if (item && item.type === "agent_message" && typeof item.text === "string") last = item.text;
