  159: /**
  160:  * Whether a turn could reach a fallback, as far as can be decided offline,
  161:  * in the product's own order (`app/api/chat/route.ts`, `attemptFallback`):
  162:  * the gate (`autoFallbackScope`), then `decideFallback` under the stated
  163:  * hypothesis, then the one candidate it names fitted under dispatch's cap
  164:  * the way `planAttemptExecution` fits it. `refusal` names the step that
  165:  * said no: `gate:<reason>`, `decision:<reason>`, or
  166:  * `candidate_context_window_exceeded`.
  167:  *
  168:  * `planAttemptExecution` itself is not called: it builds the provider client
  169:  * and the credit budget for a real dispatch, which an offline report has no
  170:  * account, credentials or reservation for. Its refusals that depend on
  171:  * those, and the two runtime checks the route makes around it, are listed
  172:  * in `unverifiedConditions` on every reachable answer, so `reachable: true`
  173:  * reads as "nothing decidable offline refused it" and not as a promise.
  174:  */
  175: export type FallbackReachability =
  176:     | {
  177:           reachable: true;
  178:           modelId: string;
  179:           dispatchFit: "fitted" | "unbounded";
  180:           dispatchOutputTokens: number | null;
  181:           /**
  182:            * Never "executable": whether the fallback would run is decided
  183:            * by the pre-dispatch check on a real request, against the
  184:            * conditions listed below, which this report cannot see.
  185:            */
  186:           execution: "unverified";
  187:           unverifiedConditions: readonly string[];
  188:       }
  189:     | { reachable: false; refusal: string };
