  453:     scope: FallbackScope,
  454:     decision: FallbackDecisionRecord,
  455:     candidate: ItemDiagnostic["fallback"]["firstCandidate"]
  456: ): FallbackReachability => {
  457:     if (!scope.allowed) return { reachable: false, refusal: `gate:${scope.reason}` };
  458:     if (decision.action !== "fallback") return { reachable: false, refusal: `decision:${decision.reason ?? decision.action}` };
  459:     if (!candidate || candidate.modelId !== decision.modelId) {
  460:         return { reachable: false, refusal: `decision:${decision.modelId} is not the candidate dispatch was asked to fit` };
  461:     }
  462:     if (candidate.dispatchFit === "exceeded") {
  463:         return { reachable: false, refusal: "candidate_context_window_exceeded" };
  464:     }
