  466:         reachable: true,
  467:         modelId: candidate.modelId,
  468:         dispatchFit: candidate.dispatchFit,
  469:         dispatchOutputTokens: candidate.dispatchOutputTokens,
  470:         execution: "unverified",
  471:         unverifiedConditions: FALLBACK_UNVERIFIED_CONDITIONS,
  472:     };
  473: };
